from pathlib import Path
import re
out=Path('.m/verify-posted-time')
out.mkdir(parents=True, exist_ok=True)
for html in ['tuyen-dung.html','index.html']:
    text=Path(html).read_text(encoding='utf-8')
    parts=[]
    for m in re.finditer(r'<script\b([^>]*)>(.*?)</script>', text, re.S|re.I):
        attrs=m.group(1)
        if re.search(r'\bsrc\s*=', attrs, re.I):
            continue
        if re.search(r'type\s*=\s*["\']application/json["\']', attrs, re.I):
